RULE = (188, 192, 182)
W = H = 1024


def render():
    fonts = json.loads(zlib.decompress(base64.b85decode(TYPE_DATA)))
    pixels = bytearray(bytes(PAPER) * W * H)

    def rect(x, y, w, h, color):
        assert 0 <= x <= x + w <= W and 0 <= y <= y + h <= H
        row = bytes(color) * w
        for yy in range(y, y + h):
            start = (yy * W + x) * 3
            pixels[start:start + w * 3] = row

    def text(x, y, value, style, color=INK):
        cursor = x
        for char in value:
            advance, dx, dy, width, height, encoded = fonts[style][char]
            mask = base64.b85decode(encoded)
            left = round(cursor) + dx
            assert left >= 0 and left + width <= W
            assert 0 <= y + dy and y + dy + height <= H
            for yy in range(height):
                for xx in range(width):
                    alpha = mask[yy * width + xx]
                    if alpha:
                        offset = ((y + dy + yy) * W + left + xx) * 3
                        for channel in range(3):
                            pixels[offset + channel] = (
                                color[channel] * alpha
                                + pixels[offset + channel] * (255 - alpha) + 127
                            ) // 255
            cursor += advance
        return cursor

    def lines(x, y, values, style, spacing, color=INK):
        for index, value in enumerate(values):
            text(x, y + index * spacing, value, style, color)

    rect(44, 32, 936, 7, RED)
    text(42, 48, 'DUNIA HARI INI', 'masthead')
    text(46, 124, 'RABU, 25 NOVEMBER 2026', 'label', RED)
    text(708, 124, '5 BERITA / 1 HARI', 'label')
    rect(44, 160, 936, 2, INK)

    text(44, 179, 'WASHINGTON, AS  /  PERDAGANGAN', 'label', RED)
    lines(42, 207, ['AS mengusulkan', 'kenaikan tarif'], 'lead', 47)
    lines(44, 310, ['Tambahan 20% untuk barang China;',
                    '14 mitra dagang menjadi sasaran.',
                    'Masih usulan, belum diberlakukan.'], 'body', 29)
    text(44, 402, 'Sumber: Reuters / NDTV, 25 Nov', 'source', MUTED)

    # Cargo containers make the trade story legible without a stock photo.
    text(680, 185, '+20%', 'figure', RED)
    text(690, 263, 'USUL TARIF CHINA', 'source', RED)
    for x, y, width, color in [(664, 303, 140, MUTED), (812, 303, 140, RED),
                                (700, 358, 216, INK)]:
        rect(x, y, width, 45, color)
        for stripe in range(x + 12, x + width - 5, 14):
            rect(stripe, y + 7, 2, 31, PAPER)
    rect(655, 410, 305, 3, INK)
    rect(44, 444, 936, 2, INK)

    text(44, 466, 'JIUQUAN, CHINA  /  ANTARIKSA', 'label', RED)
    lines(44, 494, ['Astronaut Pakistan', 'menuju Tiangong'], 'headline', 35)
    lines(44, 568, ['Shenzhou-24 membawa Zeeshan Ali,',
                    'orang asing pertama dalam misi',
                    'berawak China, menuju Tiangong,',
                    'stasiun antariksa milik China.'], 'body', 25)
    text(44, 676, 'Sumber: DW / Reuters, AFP, AP', 'source', MUTED)

    text(540, 466, 'CANBERRA, AUSTRALIA  /  DIPLOMASI', 'label', RED)
    lines(540, 494, ['Pakta keamanan', 'di Pasifik'], 'headline', 35)
    lines(540, 574, ['Australia dan Kepulauan Solomon',
                     'meneken perjanjian: tak ada basis',
                     'militer asing di Kepulauan Solomon.'], 'body', 28)
    text(540, 665, 'Sumber: Nine, 25 Nov', 'source', MUTED)

    rect(510, 470, 1, 446, RULE)
    rect(44, 704, 936, 1, RULE)
    text(44, 725, 'CARTAGENA, KOLOMBIA  /  KEAMANAN', 'label', RED)
    lines(44, 753, ['Sandera supermarket', 'berhasil dibebaskan'], 'headline', 35)
    lines(44, 833, ['Pasukan menyerbu setelah penyanderaan',
                    'hampir sehari. Presiden menyatakan',
                    'semua sandera berhasil diselamatkan.'], 'body', 28)
    text(44, 924, 'Sumber: AFP / Jiji Press, 25 Nov', 'source', MUTED)

    text(540, 725, 'RAS TANURA, ARAB SAUDI  /  KONFLIK', 'label', RED)
    lines(540, 753, ['Koalisi: empat drone', 'berhasil dicegat'], 'headline', 35)
    lines(540, 833, ['Koalisi pimpinan Saudi melaporkan',
                     'pencegatan di atas Ras Tanura.',
                     'Penilaian awal: tidak ada yang terluka.'], 'body', 28)
    text(540, 924, 'Sumber: Anadolu, 25 Nov', 'source', MUTED)

    rect(44, 964, 936, 2, INK)
    text(44, 980, 'RINGKASAN DUNIA', 'source', RED)
    text(541, 980, 'Laporan 25 Nov 2026 / Ilustrasi skematis', 'source', MUTED)

    def chunk(kind, data):
        return (struct.pack('>I', len(data)) + kind + data
                + struct.pack('>I', zlib.crc32(kind + data)))

    scanlines = b''.join(b'\0' + pixels[y * W * 3:(y + 1) * W * 3]
                         for y in range(H))
    png = (b'\x89PNG\r\n\x1a\n'
           + chunk(b'IHDR', struct.pack('>IIBBBBB', W, H, 8, 2, 0, 0, 0))
           + chunk(b'IDAT', zlib.compress(scanlines, 9)) + chunk(b'IEND', b''))
    assert len(png) <= 1048576
    return png


def main():
    output = Path(os.environ.get('MAKEFUN_OUTPUT_DIR', '/output'))
    output.mkdir(parents=True, exist_ok=True)
    destination = output / 'entry.png'
    destination.write_bytes(render())
    destination.chmod(0o644)


if __name__ == '__main__':
    main()
